import os
import json
import base64
from typing import Any, Dict, List, Union

from openai import OpenAI


def _load_image_input(receipt: Union[str, bytes, bytearray]) -> str:
    if isinstance(receipt, (bytes, bytearray)):
        b64 = base64.b64encode(receipt).decode("utf-8")
        return f"data:image/png;base64,{b64}"

    if not isinstance(receipt, str):
        raise TypeError("receipt must be a file path, image bytes, or a base64/data URL string")

    if receipt.startswith("data:image/"):
        return receipt

    if os.path.exists(receipt):
        with open(receipt, "rb") as f:
            b64 = base64.b64encode(f.read()).decode("utf-8")
        return f"data:image/png;base64,{b64}"

    try:
        base64.b64decode(receipt, validate=True)
        return f"data:image/png;base64,{receipt}"
    except Exception as e:
        raise ValueError("receipt string must be a valid file path, base64 image, or data URL") from e


def extract_receipt_fields(receipt: Union[str, bytes, bytearray]) -> Dict[str, Any]:
    """
    Extract merchant, tax, total, and items from a receipt image.

    Returns:
        {
            "merchant": str | None,
            "tax": str | None,
            "total": str | None,
            "items": [
                {"name": str | None, "quantity": float | int | None, "price": str | None, "amount": str | None}
            ]
        }
    """
    client = OpenAI(api_key=os.getenv("OPENAI_API_KEY"))
    image_url = _load_image_input(receipt)

    schema = {
        "name": "receipt_extraction",
        "schema": {
            "type": "object",
            "additionalProperties": False,
            "properties": {
                "merchant": {"type": ["string", "null"]},
                "tax": {"type": ["string", "null"]},
                "total": {"type": ["string", "null"]},
                "items": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "additionalProperties": False,
                        "properties": {
                            "name": {"type": ["string", "null"]},
                            "quantity": {"type": ["number", "null"]},
                            "price": {"type": ["string", "null"]},
                            "amount": {"type": ["string", "null"]},
                        },
                        "required": ["name", "quantity", "price", "amount"],
                    },
                },
            },
            "required": ["merchant", "tax", "total", "items"],
        },
        "strict": True,
    }

    response = client.responses.create(
        model="gpt-4.1-mini",
        input=[
            {
                "role": "system",
                "content": "Extract structured fields from receipts. Return only the requested JSON matching the schema.",
            },
            {
                "role": "user",
                "content": [
                    {"type": "input_text", "text": "Extract merchant, tax, total, and line items from this receipt."},
                    {"type": "input_image", "image_url": image_url},
                ],
            },
        ],
        response_format={"type": "json_schema", "json_schema": schema},
    )

    text = getattr(response, "output_text", None)
    if not text:
        for output in getattr(response, "output", []):
            for content in getattr(output, "content", []):
                if getattr(content, "type", None) == "output_text":
                    text = getattr(content, "text", None)
                    break
            if text:
                break

    if not text:
        raise ValueError("No JSON content returned by the model")

    return json.loads(text)
